import Vue from 'vue'
import VueRouter from 'vue-router'
import Accueil from '../views/AccueilView.vue'
import Competence1 from '../views/Competence1View.vue'
import Competence2 from '../views/Competence2View.vue'


Vue.use(VueRouter)

const routes =[
  { path: '/', name: 'Accueil', component: Accueil },
  { path: '/competence1', name: 'Competence1', component: Competence1 },
  { path: '/competence2', name: 'Competence2', component: Competence2 },
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
